    db = SessionLocal()
    try:
        project = self.project_manager.db_manager.get_project(db, name=self.project_name)
        config = self.project_manager._get_project_config(self.project_name)
        all_assets = self.project_manager.db_manager.list_project_assets(db, project_id=project.id)
    except Exception as e:
        messagebox.showerror("Error", f"Could not load project configuration: {e}")
        self.destroy()
        return {}
    finally:
        db.close()

    def get_best_path(category, filename_from_config=None):
        # Prefer path from DB asset table if found
        asset = None
        if filename_from_config:
            filename = os.path.basename(filename_from_config)
            # Filter by category and exact filename
            asset = next((a for a in all_assets if a.category == category and a.filename == filename), None)

        # If not found by filename, or filename was null, try any asset of that category (for singletons like ArUco)
        if not asset and category in ["aruco_ref", "object_ref", "ideal_checker", "project_specific_color_checker"]:
            asset = next((a for a in all_assets if a.category == category), None)

        if asset and asset.file_path and Path(asset.file_path).exists():
            return Path(asset.file_path)

        # Fallback to config string resolution
        if filename_from_config:
            return self._resolve_path(filename_from_config)
        return None

    targets = {}
    cc_config = config.color_correction

    targets["ideal_checker"] = {
        "label": "Ideal Reference Color Checker", 
        "abs_path": get_best_path("ideal_checker", cc_config.reference_color_checker_path), 
        "rel_path": cc_config.reference_color_checker_path
    }
    targets["project_checker"] = {
        "label": "Project-Specific Color Checker", 
        "abs_path": get_best_path("project_specific_color_checker", cc_config.project_specific_color_checker_path), 
        "rel_path": cc_config.project_specific_color_checker_path
    }

    if config.object_reference_path:
        targets["object_ref"] = {
            "label": "Object Reference Image", 
            "abs_path": get_best_path("object_ref", config.object_reference_path), 
            "rel_path": config.object_reference_path
        }

    for key, path_str in config.masking.drawing_layers.items():
        targets[f"drawing_{key}"] = {
            "label": f"Drawing Layer '{key}'", 
            "abs_path": get_best_path("drawing_layer", path_str), 
            "rel_path": path_str
        }

    geo_config = config.geometrical_alignment
    if geo_config.reference_path:
        targets["aruco_ref"] = {
            "label": "ArUco Reference Image", 
            "abs_path": get_best_path("aruco_ref", geo_config.reference_path), 
            "rel_path": geo_config.reference_path
        }
    return targets

