def _delete_color_checker(self, asset):
    if not messagebox.askyesno("Confirm Deletion", f"Permanently delete checker '{asset.filename}'? This will unlink it from any calibration images."):
        return

    db = SessionLocal()
    try:
        # 1. Physical file
        if os.path.exists(asset.file_path):
            os.remove(asset.file_path)

        # 2. Unlink any images pointing to this checker
        calibration_assets = self.project_manager.db_manager.list_project_assets(db, project_id=self.project_id)
        for cal_asset in calibration_assets:
            if cal_asset.parent_asset_id == asset.id:
                cal_asset.parent_asset_id = None

        # 3. Remove asset record
        target = db.query(self.project_manager.db_manager.ProjectAsset).filter_by(id=asset.id).first()
        if target:
            db.delete(target)

        db.commit()
        self.project_manager.clear_cache_for_project(self.project_name)
        self.refresh_all_statuses() # Refreshes both lists and singleton labels
    finally:
        db.close()

