def refresh_all_statuses(self):
    # Clear all thumbnail references once before rebuilding lists
    self.thumbnail_references.clear()

    # Refresh config file statuses
    for key, info in self.target_files.items():
        widget = self.file_widgets.get(key)
        if not widget:
            continue

        # Special handling for Ideal Checker preview (Standard generated image)
        if key == 'ideal_checker':
            preview_path = config.GLOBAL_COLOR_CHECKER_REFERENCE_PATH
            if preview_path.exists():
                try:
                    img = Image.open(preview_path)
                    img.thumbnail((100, 100))
                    photo = ImageTk.PhotoImage(img)
                    self.thumbnail_references.append(photo)
                    # Find the parent row frame to insert preview
                    row_frame = widget.master.master
                    # Check if preview already exists to update or create
                    found = False
                    for child in row_frame.winfo_children():
                        if getattr(child, 'is_preview', False):
                            child.config(image=photo)
                            found = True
                            break
                    if not found:
                        lbl = ttk.Label(row_frame, image=photo)
                        lbl.is_preview = True
                        lbl.pack(side="left", padx=10, before=widget.master)
                except: pass

        abs_path = info.get("abs_path")
        if abs_path and abs_path.exists() and abs_path.is_file():
            widget.config(text="Found", foreground="green")
            if key == 'ideal_checker':
                self._validate_color_checker(abs_path)
        else:
            widget.config(text="Missing", foreground="red")
            if key == 'ideal_checker' and key in self.validation_widgets:
                self.validation_widgets[key].config(text="Pending file...", foreground="gray")

    # Refresh lists
    self._refresh_color_checkers_list()
    self._refresh_calibration_images_list()

