import React, { useRef, useState } from 'react';
import { FileCheck, FileX, Plus, Trash2, Image as ImageIcon, Upload, Loader2 } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import apiClient from '../../api/client';

interface FilePlacerProps {
  projectId: string;
}

export const FilePlacer: React.FC<FilePlacerProps> = ({ projectId }) => {
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const filesInputRef = useRef<HTMLInputElement>(null);
  const [activeUpload, setActiveUpload] = useState<{ category: string, layerKey?: string } | null>(null);

  const { data: projectFiles, isLoading } = useQuery({
    queryKey: ['project-files', projectId],
    queryFn: async () => {
      const response = await apiClient.get(`/api/projects/${projectId}/files`);
      return response.data;
    }
  });

  const checkers = projectFiles?.config_files.filter((f: any) => f.category.includes('checker')) || [];

  const { data: validationData, isLoading: isValidating } = useQuery({
    queryKey: ['validation', projectId],
    queryFn: async () => (await apiClient.get(`/api/projects/${projectId}/dataset/validate-checker`)).data,
    enabled: !!projectFiles?.config_files.find((f: any) => f.key === 'ideal_checker' && f.exists),
    retry: false
  });

  const deleteMutation = useMutation({
    mutationFn: async (filename: string) => {
      await apiClient.delete(`/api/projects/${projectId}/dataset/calibration_images/${filename}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
      queryClient.invalidateQueries({ queryKey: ['validation', projectId] });
    }
  });

  const uploadMutation = useMutation({
    mutationFn: async ({ file, category, layerKey, parentAssetId }: { file: File, category: string, layerKey?: string, parentAssetId?: string }) => {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('category', category);
      if (layerKey) formData.append('layer_key', layerKey);
      if (parentAssetId) formData.append('parent_asset_id', parentAssetId);
      await apiClient.post(`/api/projects/${projectId}/files/upload`, formData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
      queryClient.invalidateQueries({ queryKey: ['validation', projectId] });
      setActiveUpload(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  });

  const linkMutation = useMutation({
    mutationFn: async ({ filename, parentAssetId }: { filename: string, parentAssetId: string }) => {
      const formData = new FormData();
      formData.append('parent_asset_id', parentAssetId);
      await apiClient.post(`/api/projects/${projectId}/dataset/calibration_images/${filename}/link`, formData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['project-files', projectId] });
    }
  });

  // Group calibration images
  const groupedImages: Record<string, any[]> = {};
  projectFiles?.calibration_images?.forEach((img: any) => {
    const gid = img.parent_asset_id || 'none';
    if (!groupedImages[gid]) groupedImages[gid] = [];
    groupedImages[gid].push(img);
  });

  const handleUploadClick = (category: string, layerKey?: string) => {
    if (fileInputRef.current) fileInputRef.current.value = '';
    setActiveUpload({ category, layerKey });
    setTimeout(() => fileInputRef.current?.click(), 10);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0] && activeUpload) {
      uploadMutation.mutate({
        file: e.target.files[0],
        category: activeUpload.category,
        layerKey: activeUpload.layerKey
      });
    }
  };

  const handleAddImagesClick = () => {
    filesInputRef.current?.click();
  };

  const handleMultiFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      for (const file of files) {
        try {
          await uploadMutation.mutateAsync({ file, category: 'calibration_image' });
        } catch (err) { console.error(err); }
      }
    }
    if (filesInputRef.current) filesInputRef.current.value = '';
    e.target.value = '';
  };

  const handleDeleteImage = (filename: string) => {
    if (confirm(`Are you sure you want to delete ${filename}?`)) {
      deleteMutation.mutate(filename);
    }
  };

  const handleLinkChange = (filename: string, parentId: string) => {
    linkMutation.mutate({ filename, parentAssetId: parentId });
  };

  const getFullUrl = (path?: string) => {
    if (!path) return '';
    if (path.startsWith('http')) return path;
    const baseUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';
    return `${baseUrl}${path}`;
  };

  if (isLoading) return <div className="flex justify-center p-10"><Loader2 className="animate-spin text-green-600" /></div>;

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
      <input type="file" ref={filesInputRef} className="hidden" multiple onChange={handleMultiFileChange} accept=".jpg,.jpeg,.png" />

      {/* Config Section */}
      <section className="bg-neutral-900 border border-neutral-800 rounded-xl overflow-hidden">
        <div className="px-4 py-3 border-b border-neutral-800 bg-neutral-800/30 flex items-center justify-between">
          <span className="text-xs font-bold uppercase tracking-wider text-neutral-400">Project Configuration Files</span>
          <button
            onClick={() => handleUploadClick('project_specific_color_checker')}
            className="flex items-center gap-1 text-[10px] bg-blue-600/20 hover:bg-blue-600 text-blue-400 hover:text-white px-2 py-1 rounded font-bold transition-all border border-blue-500/30"
          >
            <Plus className="w-3 h-3" /> REGISTER NEW CHECKER
          </button>
        </div>
        <div className="p-4 divide-y divide-neutral-800/50">
          {projectFiles?.config_files?.map((file: any) => (
            <div key={file.key} className="py-3 flex items-start justify-between group">
              <div className="flex flex-col">
                <span className="text-sm font-medium">{file.label}</span>
                <span className="text-[10px] text-neutral-500 font-mono truncate max-w-md" title={file.rel_path}>{file.rel_path}</span>
                {file.key === 'ideal_checker' && file.exists && (
                  <div className="flex items-center mt-1 gap-2">
                    {isValidating ? (
                      <span className="text-[10px] text-orange-500 flex items-center gap-1"><Loader2 className="w-3 h-3 animate-spin" /> Validating...</span>
                    ) : validationData ? (
                      <span className={`text-[10px] font-bold ${validationData.success ? 'text-green-500' : 'text-orange-500'}`}>
                        {validationData.message}
                      </span>
                    ) : null}
                  </div>
                )}
              </div>
              <div className="flex items-center gap-4 mt-1">
                <div className="flex items-center gap-1.5">
                  {file.exists ? (
                    <><FileCheck className="w-3.5 h-3.5 text-green-500" /><span className="text-[10px] text-green-500 font-bold">FOUND</span></>
                  ) : (
                    <><FileX className="w-3.5 h-3.5 text-red-500" /><span className="text-[10px] text-red-500 font-bold">MISSING</span></>
                  )}
                </div>
                <button
                  onClick={() => handleUploadClick(file.category, file.layer_key)}
                  className="p-1.5 hover:bg-neutral-800 rounded transition-colors text-neutral-400 hover:text-white"
                >
                  <Upload className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* Grouped Calibration Images */}
      <div className="space-y-8">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-bold uppercase tracking-widest text-neutral-500">Calibration Groups</h3>
          <button
            onClick={handleAddImagesClick}
            className="flex items-center gap-1 text-[10px] bg-green-600 hover:bg-green-500 text-white px-3 py-1.5 rounded-lg font-bold transition-all shadow-lg shadow-green-900/20"
          >
            <Plus className="w-3 h-3" /> UPLOAD TO PROJECT
          </button>
        </div>

        {Object.keys(groupedImages).length === 0 && (
          <div className="py-20 text-center bg-neutral-900/50 border border-neutral-800 border-dashed rounded-2xl text-neutral-600 italic text-sm">
            No calibration images found. Use the button above to start.
          </div>
        )}

        {Object.entries(groupedImages).sort(([a], [b]) => {
          if (a === 'none') return -1;
          if (b === 'none') return 1;
          return a.localeCompare(b);
        }).map(([gid, imgs]) => {
          const checker = projectFiles.config_files.find((f: any) => f.id === gid);
          const checkerName = checker ? checker.filename : 'Default / Unlinked';

          return (
            <section key={gid} className="space-y-4">
              <div className="flex items-center gap-3 px-2">
                <div className={`w-2 h-2 rounded-full ${gid === 'none' ? 'bg-neutral-700' : 'bg-green-500'}`} />
                <h4 className="text-xs font-bold text-neutral-300">Group: <span className="text-green-500 font-mono">{checkerName}</span></h4>
                <div className="flex-1 h-[1px] bg-neutral-800" />
                <span className="text-[10px] text-neutral-600 font-bold uppercase tracking-tighter">{imgs.length} Images</span>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
                {imgs.map((img: any) => (
                  <div key={img.filename} className="group relative bg-neutral-950 border border-neutral-800 rounded-xl p-2.5 hover:border-neutral-600 transition-all shadow-sm">
                    <div className="aspect-square bg-neutral-900 rounded-lg mb-3 flex items-center justify-center overflow-hidden border border-neutral-800/50">
                      {img.url ? (
                        <img src={getFullUrl(img.url)} alt={img.filename} className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                      ) : (
                        <ImageIcon className="w-8 h-8 text-neutral-800" />
                      )}
                    </div>

                    <div className="space-y-2">
                      <div className="text-[10px] font-mono text-neutral-400 truncate" title={img.filename}>
                        {img.filename}
                      </div>

                      <div className="relative">
                        <select
                          value={img.parent_asset_id || 'none'}
                          onChange={(e) => handleLinkChange(img.filename, e.target.value)}
                          className="w-full bg-neutral-900 border border-neutral-800 rounded-md px-2 py-1 text-[9px] text-neutral-500 focus:outline-none focus:border-green-600 appearance-none hover:text-neutral-300 transition-colors"
                        >
                          <option value="none">Change Link...</option>
                          {checkers.map((c: any) => (
                            <option key={c.id} value={c.id}>{c.filename}</option>
                          ))}
                        </select>
                      </div>
                    </div>

                    <button
                      onClick={() => handleDeleteImage(img.filename)}
                      className="absolute top-4 right-4 p-1.5 bg-red-600/90 hover:bg-red-600 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-all transform translate-y-1 group-hover:translate-y-0"
                      title="Delete Image"
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  </div>
                ))}
              </div>
            </section>
          );
        })}
      </div>
    </div>
  );
};

